//! The Python backend (design.md 18.2, 18.14): dataclasses, enums and type aliases, one module per
//! declaration, with TypeDefs for the runtime (tsurara-client, `runtimes/python`), and one module per
//! operation with its OperationDef and call function.

pub mod external;
mod mocks;
pub mod naming;
mod operations;
mod print;
mod vendor;

use tsurara_backend::{Backend, Emitted, Error, Markers};
use tsurara_lower::{Capabilities, Inheritance, lower};
use tsurara_sem::{Model, Options};

/// The first line of every generated file.
pub const HEADER: &str = "# Generated by tsurara. Do not edit.";

/// What Python can express (design.md 18.5.2). Tagged unions are written as union aliases; their tags
/// live in the TypeDefs.
pub const CAPABILITIES: Capabilities = Capabilities {
    inline_records: false,
    structural_unions: true,
    tagged_unions: true,
    intersections: false,
    inheritance: Inheritance::Single,
    literal_types: true,
    enums: tsurara_lower::Enums::Any,
    tuples: true,
    strict_decoding: true,
    nullable_primitives: true,
    recursion_by_value: true,
};

/// Options of the `python` section.
#[derive(Debug, Clone, Default)]
pub struct PythonOptions {
    /// Enums and discriminators reject unlisted values instead of keeping them (design.md 18.5.3).
    pub strict_enums: bool,
    /// Emit mock factories and routes for `MockRouter` under `mocks/` (`python.mocks`).
    pub mocks: bool,
}

#[derive(Debug, Clone, Default)]
pub struct Python {
    pub options: PythonOptions,
}

impl Backend for Python {
    fn id(&self) -> &'static str {
        "python"
    }

    fn markers(&self) -> Markers {
        Markers {
            generated: HEADER.to_owned(),
            version: None,
            sidecars: Vec::new(),
        }
    }

    fn emit(&self, model: &Model, opts: &Options) -> Result<Emitted, Error> {
        let caps = Capabilities {
            strict_decoding: !self.options.strict_enums,
            ..CAPABILITIES
        };
        let (module, mut warnings) = lower(model, &caps);
        let (files, more, manifest) = print::print(model, &module, opts, self.options.mocks);
        warnings.extend(more);
        Ok(Emitted {
            files,
            warnings,
            manifest: Some(manifest),
        })
    }

    fn options_json(&self) -> serde_json::Value {
        serde_json::json!({ "strictEnums": self.options.strict_enums, "mocks": self.options.mocks })
    }

    fn example(&self, input: &tsurara_backend::ExampleInput) -> Option<tsurara_backend::Example> {
        let caps = Capabilities {
            strict_decoding: !self.options.strict_enums,
            ..CAPABILITIES
        };
        let (module, _) = lower(input.model, &caps);
        let names = print::assign(input.model, &module, input.opts);
        operations::example(&module, &names, input)
    }
}

/// Builds the model from a loaded definition and generates Python.
pub fn generate(
    set: &tsurara_loader::DocumentSet,
    opts: &Options,
    python: &PythonOptions,
) -> Result<tsurara_backend::Output, Error> {
    let backend = Python {
        options: python.clone(),
    };
    tsurara_backend::generate(&backend, set, opts)
}
